std::vector<std::vector<cg3::Point2d>> result;

// Create CGAL kernel and Delaunay triangulation
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Delaunay_triangulation_2<K> DT;
typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
typedef CGAL::Voronoi_diagram_2<DT,AT,AP> VD;

// Create Delaunay triangulation
DT dt;
for (const cg3::Point2d& p : sites) {
    dt.insert(K::Point_2(p.x(), p.y()));
}

// Create Voronoi diagram
VD vd(dt);

// Iterate through all Voronoi cells
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (vd.is_infinite(fit)) continue; // Skip infinite faces

    std::vector<cg3::Point2d> cell;
    // Get the circulator for the outer face of the cell
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;

    // Collect all vertices of the cell
    do {
        // Get the source point of the halfedge (Voronoi vertex)
        K::Point_2 p = circ->source()->point();
        cell.push_back(cg3::Point2d(p.x(), p.y()));
        ++circ;
    } while (circ != start);

    // Only add non-empty cells
    if (!cell.empty()) {
        result.push_back(cell);
    }
}

// Handle the case where we need to collect vertices from all Voronoi vertices
// We also need to consider the case where the Voronoi diagram has unbounded cells
// For unbounded cells, we need to collect the rays and extend them to a bounding box
// But the specification doesn't specify how to handle unbounded cells, so we'll follow
// the pattern in the second overload which seems to handle this by converting to a format
// that can handle unbounded cells

// Alternative approach: use the second overload's logic but return the raw cells
// Let's try a different approach using the Voronoi diagram's vertices directly

result.clear();
std::vector<std::vector<cg3::Point2d>> cells;

// We'll use a different approach: iterate through all Voronoi vertices and collect
// the cells they belong to
std::map<cg3::Point2d, std::vector<cg3::Point2d>> cellMap;

// For each site, we'll find its Voronoi cell
for (DT::Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    // For each Delaunay triangle, we get the circumcenter which is a Voronoi vertex
    K::Point_2 circumcenter = dt.dual(fit);
    cg3::Point2d v(circumcenter.x(), circumcenter.y());

    // The Voronoi cell corresponds to the site at the center of the triangle
    // Get the three sites of the triangle
    std::vector<cg3::Point2d> cell;
    for (int i = 0; i < 3; ++i) {
        K::Point_2 site = fit->vertex(i)->point();
        cell.push_back(cg3::Point2d(site.x(), site.y()));
    }

    // We need to associate the Voronoi vertex with the correct cell
    // This approach is getting complex - let's use the standard CGAL approach
}

// Let's use the standard approach from the second overload's logic
// We'll use the Voronoi diagram's face iterator to get the cells
result.clear();

// Create the Voronoi diagram again
DT dt2;
for (const cg3::Point2d& p : sites) {
    dt2.insert(K::Point_2(p.x(), p.y()));
}

VD vd2(dt2);

// For each face in the Voronoi diagram, we get the cell
for (VD::Face_iterator fit = vd2.faces_begin(); fit != vd2.faces_end(); ++fit) {
    if (vd2.is_infinite(fit)) continue; // Skip infinite faces

    std::vector<cg3::Point2d> cell;
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;

    do {
        // Get the Voronoi vertex (point)
        K::Point_2 p = circ->source()->point();
        cell.push_back(cg3::Point2d(p.x(), p.y()));
        ++circ;
    } while (circ != start);

    if (!cell.empty()) {
        result.push_back(cell);
    }
}

// Handle unbounded cells - we need to collect them too
// For unbounded cells, we need to collect the rays and extend them
// We'll collect all faces including infinite ones
for (VD::Face_iterator fit = vd2.faces_begin(); fit != vd2.faces_end(); ++fit) {
    if (vd2.is_infinite(fit)) {
        std::vector<cg3::Point2d> cell;
        VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
        VD::Ccb_halfedge_circulator start = circ;

        // For unbounded cells, we need to collect the vertices and extend the rays
        // We'll collect the finite vertices first
        do {
            if (!circ->is_finite()) {
                // This is a ray - we need to extend it
                // We'll approximate by extending the ray to a large distance
                // Get the direction of the ray
                K::Point_2 source = circ->source()->point();
                K::Point_2 target = circ->target()->point();
                K::Vector_2 dir = target - source;
                // Extend the ray by a large distance
                double scale = 1e10;
                K::Point_2 extended = source + dir * scale;
                cell.push_back(cg3::Point2d(extended.x(), extended.y()));
            } else {
                K::Point_2 p = circ->source()->point();
                cell.push_back(cg3::Point2d(p.x(), p.y()));
            }
            ++circ;
        } while (circ != start);

        if (!cell.empty()) {
            result.push_back(cell);
        }
    }
}

// The above approach might be overcomplicating. Let's look at the second overload
// which uses the first overload's result. The first overload should return the
// Voronoi cells as vectors of vertices. The standard approach is to use the
// Voronoi diagram's face iterator and collect the vertices of each cell.

// Let's simplify and use the standard approach:
result.clear();

// Create Delaunay triangulation
DT dt3;
for (const cg3::Point2d& p : sites) {
    dt3.insert(K::Point_2(p.x(), p.y()));
}

// Create Voronoi diagram
VD vd3(dt3);

// For each face in the Voronoi diagram, collect the vertices
for (VD::Face_iterator fit = vd3.faces_begin(); fit != vd3.faces_end(); ++fit) {
    // Skip infinite faces for now - we'll handle them later
    if (vd3.is_infinite(fit)) {
        continue;
    }

    std::vector<cg3::Point2d> cell;
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;

    do {
        K::Point_2 p = circ->source()->point();
        cell.push_back(cg3::Point2d(p.x(), p.y()));
        ++circ;
    } while (circ != start);

    if (!cell.empty()) {
        result.push_back(cell);
    }
}

// Now handle infinite faces by extending the rays
for (VD::Face_iterator fit = vd3.faces_begin(); fit != vd3.faces_end(); ++fit) {
    if (!vd3.is_infinite(fit)) {
        continue;
    }

    std::vector<cg3::Point2d> cell;
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;

    // We need to collect the vertices and extend the rays
    // For unbounded cells, we'll extend the rays to a large distance
    // We'll use a bounding box approach - extend rays to a large square
    double bound = 1e10;

    do {
        if (circ->is_finite()) {
            K::Point_2 p = circ->source()->point();
            cell.push_back(cg3::Point2d(p.x(), p.y()));
        } else {
            // This is a ray - we need to extend it
            // Get the direction of the ray
            K::Point_2 source = circ->source()->point();
            K::Point_2 target = circ->target()->point();
            K::Vector_2 dir = target - source;
            // Normalize the direction
            double len = std::sqrt(dir.x() * dir.x() + dir.y() * dir.y());
            if (len > 1e-10) {
                dir = dir / len;
                // Extend the ray by a large distance
                K::Point_2 extended = source + dir * bound;
                cell.push_back(cg3::Point2d(extended.x(), extended.y()));
            }
        }
        ++circ;
    } while (circ != start);

    if (!cell.empty()) {
        result.push_back(cell);
    }
}

// Return the result
return result;

