std::vector<std::vector<Point2d>> result;
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Delaunay_triangulation_2<K> DT;
typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
typedef CGAL::Voronoi_diagram_2<DT,AT,AP> VD;

DT dt;
for (const Point2d& p : points) {
    dt.insert(K::Point_2(p.x, p.y));
}

VD vd(dt);

for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (vd.is_infinite(fit)) continue;
    std::vector<Point2d> cell;
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;
    do {
        K::Point_2 p = circ->source()->point();
        cell.push_back(Point2d(p.x(), p.y()));
        ++circ;
    } while (circ != start);
    if (!cell.empty()) {
        result.push_back(cell);
    }
}

double bound = 1e10;
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (!vd.is_infinite(fit)) continue;
    std::vector<Point2d> cell;
    VD::Ccb_halfedge_circulator circ = fit->outer_ccb();
    VD::Ccb_halfedge_circulator start = circ;
    do {
        if (circ->is_finite()) {
            K::Point_2 p = circ->source()->point();
            cell.push_back(Point2d(p.x(), p.y()));
        } else {
            K::Point_2 source = circ->source()->point();
            K::Point_2 target = circ->target()->point();
            K::Vector_2 dir = target - source;
            double len = std::sqrt(dir.x() * dir.x() + dir.y() * dir.y());
            if (len > 1e-10) {
                dir = dir / len;
                K::Point_2 extended = source + dir * bound;
                cell.push_back(Point2d(extended.x(), extended.y()));
            }
        }
        ++circ;
    } while (circ != start);
    if (!cell.empty()) {
        result.push_back(cell);
    }
}

return result;
